function cacheFinishedEpisode(x){var persistent=Promise.resolve(false);try{if(navigator.storage&&navigator.storage.persist)persistent=navigator.storage.persist()}catch(e){}getSaved(x.file).then(function(rec){if(rec&&rec.blob){saved.add(x.file);render();status('الحلقة محفوظة بالفعل للاستماع دون إنترنت.');return}status('اكتمل الاستماع. جارٍ حفظ نسخة كاملة دون إنترنت — اترك الاتصال حتى تظهر رسالة اكتمال الحفظ.');return Promise.resolve(persistent).catch(function(){return false}).then(function(){return fetch(x.url,{mode:'cors'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()}).then(function(blob){if(!blob.size)throw new Error('الملف فارغ');return tx('readwrite',function(st){return st.put({file:x.file,title:x.title,blob:blob,size:blob.size,savedAt:Date.now()})})})}).then(function(){saved.add(x.file);render();status('تم حفظ '+x.file+' داخل التطبيق. تقدر تسمعها بعد كده من غير إنترنت.')})}).catch(function(e){status('انتهت الحلقة لكن تعذر حفظها للاستماع دون إنترنت ('+(e.message||'')+'). استخدم «حفظ دون إنترنت» أو «تنزيل للجهاز».')})}
function saveItem(x,btn){btn.disabled=true;btn.textContent='جارٍ التنزيل والحفظ…';status('يتم تنزيل الحلقة ('+(x.size/1048576).toFixed(1)+' ميجابايت) وحفظها محليًا. لا تغلق الصفحة حتى يكتمل.');var persist=Promise.resolve(false);try{if(navigator.storage&&navigator.storage.persist)persist=navigator.storage.persist()}catch(e){}Promise.resolve(persist).catch(function(){return false}).then(function(persistent){return fetch(x.url,{mode:'cors'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()}).then(function(blob){if(!blob.size)throw new Error('empty');return tx('readwrite',function(s){return s.put({file:x.file,title:x.title,blob:blob,size:blob.size,savedAt:Date.now()})}).then(function(){return persistent})})}).then(function(persistent){saved.add(x.file);status('تم حفظ الحلقة على هذا الجهاز. '+(persistent?'وافق المتصفح على طلب حماية التخزين من الإزالة التلقائية.':'قد يحذف المتصفح النسخة عند الحاجة إلى مساحة؛ ومسح بيانات الموقع يحذفها. تنزيل الملف للجهاز يظل الأوثق.') );render()}).catch(function(e){btn.disabled=false;btn.textContent='حفظ دون إنترنت';status('تعذر الحفظ داخل التطبيق ('+(e.message||'خطأ')+'). استخدم «تنزيل للجهاز» أو جرّب بعد الاتصال.');});}
function downloadItem(x,btn){btn.disabled=true;btn.textContent='جارٍ تجهيز التنزيل…';status('إذا كانت الحلقة محفوظة في مكتبة التطبيق فسنستخدم النسخة نفسها؛ وإلا ننزّلها الآن إلى جهازك.');getSaved(x.file).catch(function(){return null}).then(function(rec){if(rec&&rec.blob)return rec.blob;return fetch(x.url,{mode:'cors'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()})}).then(function(blob){var u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=x.file;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},60000);btn.disabled=false;btn.textContent='⬇ تنزيل للجهاز';status('بدأ تنزيل '+x.title+' كملف مستقل إلى مجلد التنزيلات في جهازك.')}).catch(function(e){btn.disabled=false;btn.textContent='⬇ تنزيل للجهاز';status('تعذر التنزيل داخل الصفحة؛ افتح مصدر الأرشيف مباشرة. '+(e.message||''));window.open(x.url+'?download=1','_blank','noopener')})}
