function downloadAllEpisodes(){if(bulkRunning){bulkCancel=true;status('جارٍ إيقاف التنزيل بعد الملف الحالي…');return}if(!catalog||!catalog.items||!catalog.items.length){status('فهرس الحلقات غير متاح.');return}var total=catalog.items.reduce(function(a,x){return a+(Number(x.size)||0)},0);var gb=(total/1e9).toFixed(1);if(!window.confirm('سيبدأ تنزيل '+catalog.items.length.toLocaleString('en-US')+' ملف MP3 بحجم إجمالي يقارب '+gb+' جيجابايت. تأكد من توفر مساحة كافية واتصال ثابت. هل تريد المتابعة؟'))return;bulkRunning=true;bulkCancel=false;var btn=bulkButton();if(btn)btn.textContent='إيقاف تنزيل الكل';var folderPromise=Promise.resolve(null);if(window.showDirectoryPicker&&window.isSecureContext){try{folderPromise=window.showDirectoryPicker({mode:'readwrite'}).catch(function(e){if(e&&e.name==='AbortError')throw e;return null})}catch(e){folderPromise=Promise.resolve(null)}}folderPromise.then(function(folder){var items=catalog.items;function report(i,x){if(i===1||i%10===0||i===items.length)status('تنزيل المكتبة: '+i.toLocaleString('en-US')+' / '+items.length.toLocaleString('en-US')+' — '+x.file+(folder?' (إلى المجلد الذي اخترته)':' (قد يطلب المتصفح السماح بالتنزيلات المتعددة)'))}function getBulkBlob(x){if(!saved.has(x.file))return fetch(x.url,{mode:'cors'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()});return getSaved(x.file).catch(function(){return null}).then(function(rec){if(rec&&rec.blob)return rec.blob;return fetch(x.url,{mode:'cors'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()})})}function writeBlobToHandle(blob,handle){return handle.createWritable().then(function(w){if(!blob.stream){return blob.arrayBuffer().then(function(b){return w.write(b).then(function(){return w.close()})})}var reader=blob.stream().getReader();function pump(){if(bulkCancel)return reader.cancel().then(function(){return w.abort()});return reader.read().then(function(v){if(v.done)return w.close();return w.write(v.value).then(pump)})}return pump()})}function oneToFolder(x){return getBulkBlob(x).then(function(blob){return folder.getFileHandle(x.file,{create:true}).then(function(handle){return writeBlobToHandle(blob,handle)})})}function oneAsBrowserDownload(x){return getBulkBlob(x).then(function(blob){var u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=x.file;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},120000)})}var chain=Promise.resolve();items.forEach(function(x,i){chain=chain.then(function(){if(bulkCancel)return;if(!bulkCancel)report(i+1,x);return (folder?oneToFolder(x):oneAsBrowserDownload(x)).then(function(){if(!folder)return sleep(1100)}).catch(function(e){bulkCancel=true;throw new Error(x.file+': '+(e.message||'تعذر التنزيل'))})})});return chain.then(function(){status(bulkCancel?'تم إيقاف التنزيل بناءً على طلبك. الملفات التي اكتملت موجودة في المجلد/التنزيلات.':'اكتمل تنزيل جميع ملفات المكتبة ('+items.length.toLocaleString('en-US')+' ملف).')}).catch(function(e){status('توقف التنزيل عند '+(e.message||'خطأ')+'. يمكنك الضغط على «تنزيل الكل» للبدء من جديد أو تنزيل الحلقة منفردة.')}).finally(function(){bulkRunning=false;bulkCancel=false;if(btn)btn.textContent='⬇ تنزيل المكتبة كلها'})}).catch(function(e){bulkRunning=false;bulkCancel=false;if(btn)btn.textContent='⬇ تنزيل المكتبة كلها';if(e&&e.name==='AbortError')status('أُلغيت عملية اختيار المجلد.');else status('تعذر بدء التنزيل الجماعي.')})}
